      },
      {
        "id": "SH2-R2",
        "basis": "Snapshot provenance and freshness metadata could have strengthened the authority/freshness substitution finding by confirming staleness or waiver semantics. It was not selected, though SH2-R1 already supplied decisive evidence of previous-night local-snapshot use after API failure."
      }
    ],
    "decisive_item_located": {
      "value": "yes",
      "basis": "SH2-R1 located the authority/freshness substitution and SH2-R3 located the reconciliation-key identity mismatch; together they supported the final escalate/re-ground action."
    },
    "index_induced_new_reasoning": {
      "value": "no",
      "basis": "Initial already framed local-snapshot authority substitution, reconciliation identity, multi-subscription coverage, idempotency, and API retry behavior as live uncertainties. The final reasoning came from payload contents of SH2-R1 and SH2-R3, not from novel index-label-induced reasoning."
    },
    "post_audit_action_confidence_change_appropriate": {
